import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  random,
} from '../remotionShim';
// --- Font Loader ---
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// --- Schema ---


export type ChristmasCardProps = Record<string, any>;

// --- Helper Components ---

const Snowflake: React.FC<{
  x: number;
  yOffset: number;
  size: number;
  speed: number;
  opacity: number;
  height: number;
  frame: number;
}> = ({ x, yOffset, size, speed, opacity, height, frame }) => {
  const y = ((frame * speed) + yOffset) % (height + size * 2) - size;
  const xWiggle = Math.sin(frame / 40 + yOffset) * 15;

  return (
    <div
      style={{
        position: "absolute",
        left: x + xWiggle,
        top: y,
        width: size,
        height: size,
        borderRadius: "50%",
        backgroundColor: "white",
        opacity,
        boxShadow: "0 0 4px rgba(255, 255, 255, 0.8)",
      }}
    />
  );
};

const TreeIcon: React.FC<{ color: string; scale: number; opacity: number }> = ({
  color,
  scale,
  opacity,
}) => (
  <svg
    width="100"
    height="120"
    viewBox="0 0 100 120"
    style={{
      transform: `scale(${scale})`,
      opacity,
      marginBottom: 20,
    }}
  >
    <path
      d="M50 10 L10 50 H30 L10 90 H90 L70 50 H90 L50 10 Z"
      fill={color}
      stroke="none"
    />
    <rect x="40" y="90" width="20" height="20" fill="#8B4513" />
  </svg>
);

const ElfIcon: React.FC<{ size: number; rotation: number }> = ({ size, rotation }) => (
  <svg 
    width={size} 
    height={size} 
    viewBox="0 0 100 100" 
    style={{ 
      transform: `rotate(${rotation}deg)`,
      overflow: "visible",
      filter: "drop-shadow(0px 4px 4px rgba(0,0,0,0.3))"
    }}
  >
    <g transform="translate(50, 50)">
      {/* Sleigh */}
      <path d="M-25 20 Q-15 35 15 35 L30 35 Q40 35 45 25" stroke="#8B4513" strokeWidth="4" fill="none"/>
      <path d="M-20 20 L30 20 L35 10 L-25 10 Z" fill="#C0392B" />
      
      {/* Elf Body */}
      <path d="M-5 10 L-5 -10 L15 -10 L15 10 Z" fill="#2ECC71" />
      
      {/* Head */}
      <circle cx="5" cy="-15" r="12" fill="#F1C27D" />
      
      {/* Hat */}
      <path d="M-7 -18 Q5 -45 17 -18 Z" fill="#2ECC71" />
      <circle cx="17" cy="-18" r="4" fill="#FFFFFF" />
      
      {/* Face details */}
      <circle cx="1" cy="-15" r="1.5" fill="#333" />
      <circle cx="9" cy="-15" r="1.5" fill="#333" />
      <path d="M3 -10 Q5 -7 7 -10" stroke="#333" strokeWidth="1" fill="none" />
    </g>
  </svg>
);

const SnowRainbow: React.FC<{ 
  radius: number; 
  center: { x: number; y: number }; 
  opacity: number;
}> = ({ radius, center, opacity }) => (
  <svg
    style={{
      position: "absolute",
      left: 0,
      top: 0,
      width: "100%",
      height: "100%",
      pointerEvents: "none",
      opacity,
    }}
  >
    <defs>
      <linearGradient id="snowRainbowGrad" x1="0%" y1="0%" x2="100%" y2="0%">
        <stop offset="0%" stopColor="rgba(255,255,255,0)" />
        <stop offset="20%" stopColor="rgba(200, 230, 255, 0.4)" />
        <stop offset="50%" stopColor="rgba(255, 255, 255, 0.8)" />
        <stop offset="80%" stopColor="rgba(200, 230, 255, 0.4)" />
        <stop offset="100%" stopColor="rgba(255,255,255,0)" />
      </linearGradient>
      <filter id="glow">
        <feGaussianBlur stdDeviation="4" result="coloredBlur" />
        <feMerge>
          <feMergeNode in="coloredBlur" />
          <feMergeNode in="SourceGraphic" />
        </feMerge>
      </filter>
    </defs>
    
    {/* The Rainbow Arc */}
    <path
      d={`M ${center.x - radius} ${center.y} A ${radius} ${radius} 0 0 1 ${center.x + radius} ${center.y}`}
      fill="none"
      stroke="url(#snowRainbowGrad)"
      strokeWidth={20}
      strokeLinecap="round"
      filter="url(#glow)"
      style={{
        opacity: 0.8
      }}
    />
    {/* Inner subtle arc */}
    <path
      d={`M ${center.x - radius} ${center.y} A ${radius} ${radius} 0 0 1 ${center.x + radius} ${center.y}`}
      fill="none"
      stroke="#ffffff"
      strokeWidth={2}
      strokeDasharray="10 15"
      style={{ opacity: 0.5 }}
    />
  </svg>
);

// --- Main Component ---

const ChristmasCard: React.FC<ChristmasCardProps> = ({
  backgroundColor = "#0F2027",
  accentColor = "#C0392B",
  textColor = "#ffffff",
  transparentBackground = false,
  titleText = "Happy Holidays",
  subtitleText = "To all content creators",
  snowAmount = 80,
  durationInSeconds = 10,
}) => {
  // Switched "Inter" to "Fredoka One" for a bouncier, friendlier look
  useFontLoader(["Mountains of Christmas", "Fredoka One"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background Logic
  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  
  // Create a gradient if not transparent
  const backgroundStyle: React.CSSProperties = transparentBackground
    ? { backgroundColor: "transparent" }
    : {
        background: `linear-gradient(to bottom, ${backgroundColor}, #000000)`,
      };

  // Generate stable snowflakes based on snowAmount
  const snowflakes = useMemo(() => {
    return new Array(snowAmount).fill(true).map((_, i) => {
      const seed = i * 1234; // Deterministic seed
      return {
        x: random(seed) * width,
        yOffset: random(seed + 1) * height,
        size: interpolate(random(seed + 2), [0, 1], [2, 6]),
        speed: interpolate(random(seed + 3), [0, 1], [1, 3]),
        opacity: interpolate(random(seed + 4), [0, 1], [0.3, 0.9]),
      };
    });
  }, [snowAmount, width, height]);

  // Animations
  const entranceSpring = spring({
    frame,
    fps,
    config: { damping: 12, stiffness: 100 },
  });

  const textDelay = 20;

  // New bouncy spring animation for subtitle
  const subtitleBounce = spring({
    frame: frame - textDelay - 10, // Start slightly after title
    fps,
    config: {
      damping: 8,      // Low damping for bounce
      stiffness: 150,  // Higher stiffness for snap
      mass: 0.8,       // Lower mass for faster reaction
    },
  });

  const treeScale = spring({
    frame: frame - 10,
    fps,
    config: { mass: 0.5, stiffness: 120 },
  });

  // --- Snow Rainbow & Elf Logic ---
  const rainbowRadius = Math.min(width, height) * 0.4;
  // Position rainbow arc slightly behind the main content visual center
  const rainbowCenter = { x: width / 2, y: height * 0.6 };

  // Calculate Elf Trajectory
  // We want the elf to travel from Left (Math.PI) to Right (0) along the arc
  const elfLoopDuration = 250; // frames to cross
  const elfCycle = frame % (elfLoopDuration + 100); // 100 frame pause
  const elfProgress = interpolate(elfCycle, [0, elfLoopDuration], [0, 1], {
    extrapolateRight: "clamp"
  });
  
  // Only show elf if within duration
  const showElf = elfCycle <= elfLoopDuration;
  
  const elfAngle = interpolate(elfProgress, [0, 1], [Math.PI, 0]);
  const elfX = rainbowCenter.x + rainbowRadius * Math.cos(elfAngle);
  // Subtract Y because SVG coords go down, but circle calc assumes up is positive Y usually, 
  // but here: y = cy - R*sin(theta) works for top-half arc logic
  const elfY = rainbowCenter.y - rainbowRadius * Math.sin(elfAngle);
  
  // Calculate slope for rotation: tangent to circle
  // Angle of tangent = angle - PI/2 (90 degrees offset)
  // Convert radians to degrees for rotation prop
  // Note: we want elf upright but tilting with the slope? Or just riding flat?
  // Let's make him tilt slightly with the curve.
  const elfRotation = -((elfAngle * 180) / Math.PI) + 90; 

  const rainbowOpacity = interpolate(frame, [0, 30], [0, 1], { extrapolateLeft: "clamp" });

  return (
    <AbsoluteFill style={{ ...backgroundStyle }}>
      
      {/* Snow Layer */}
      <AbsoluteFill>
        {snowflakes.map((flake, i) => (
          <Snowflake
            key={i}
            {...flake}
            height={height}
            frame={frame}
          />
        ))}
      </AbsoluteFill>

      {/* Snow Rainbow Layer (Behind Content) */}
      <AbsoluteFill>
        <SnowRainbow 
          radius={rainbowRadius} 
          center={rainbowCenter} 
          opacity={rainbowOpacity} 
        />
        
        {/* Elf Riding */}
        {showElf && (
          <div
            style={{
              position: "absolute",
              left: elfX,
              top: elfY,
              transform: "translate(-50%, -50%)", // Center the elf icon on the path coordinates
              zIndex: 5
            }}
          >
             <ElfIcon size={60} rotation={elfRotation} />
          </div>
        )}
      </AbsoluteFill>

      {/* Content Layer */}
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          fontFamily: "Mountains of Christmas",
          color: textColor,
          textAlign: "center",
          padding: 40,
          zIndex: 10, // Ensure text is above rainbow
        }}
      >
        <div style={{ transform: `scale(${treeScale})` }}>
           <TreeIcon color={accentColor} scale={1} opacity={1} />
        </div>

        <h1
          style={{
            fontSize: width * 0.08,
            margin: "0 0 20px 0",
            textShadow: "0 4px 10px rgba(0,0,0,0.5)",
            transform: `scale(${entranceSpring})`,
            opacity: interpolate(frame, [0, 20], [0, 1]),
          }}
        >
          {titleText}
        </h1>

        <div
          style={{
            fontFamily: "Fredoka One", // Updated font
            fontSize: width * 0.035,   // Slightly larger
            fontWeight: 400,
            opacity: interpolate(frame - textDelay, [0, 10], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }),
            transform: `scale(${subtitleBounce})`, // Apply bouncy spring to scale
            maxWidth: width * 0.85,
            lineHeight: 1.4,
            color: "#e0e0e0",
            background: "rgba(255,255,255,0.15)", // Slightly brighter background
            padding: "15px 30px",
            borderRadius: 50, // More rounded/bouncy shape
            backdropFilter: "blur(4px)",
            boxShadow: "0 4px 15px rgba(0,0,0,0.2)",
          }}
        >
          {subtitleText}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default ChristmasCard;